import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Vector3, PointLight, Light } = ctx.THREE;

  const group = new Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Color palette from spec
  const colors = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    gradTop: 0x101017,
    gradBottom: 0x1a1a22,
  };

  // Grid layout constants (spec: 5.5 x 3.5 centered at origin)
  const dominantWidth = 3.25;
  const dominantHeight = 3.5;
  const secondaryWidth = 2.0;
  const secondaryHeight = 1.625;
  const gutterSize = 0.25;
  const cellDepth = 0.06;
  const chamferRadius = 0.04;
  const tickWidth = 0.4;
  const tickHeight = 0.05;
  const tickEmissive = 1.3;
  const innerPadding = 0.5;

  // Grid total dimensions
  const gridWidth = dominantWidth + gutterSize + secondaryWidth; // 5.5
  const gridHeight = dominantHeight; // 3.5

  // Cell positions (grid centered at origin)
  const gridOffsetX = -gridWidth / 2;
  const gridOffsetY = 0;

  // Dominant cell: left column, both rows
  const dominantX = gridOffsetX + dominantWidth / 2;
  const dominantY = gridOffsetY;

  // Secondary cells: right column, stacked
  const secondary1X = gridOffsetX + dominantWidth + gutterSize + secondaryWidth / 2;
  const secondary1Y = gridOffsetY + (gridHeight / 2 - secondaryHeight / 2) - (secondaryHeight + gutterSize) / 2;

  const secondary2X = secondary1X;
  const secondary2Y = gridOffsetY - (gridHeight / 2 - secondaryHeight / 2) + (secondaryHeight + gutterSize) / 2;

  // === BACKDROP PLANE ===
  const backdropGeom = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color(colors.gradTop),
      color(colors.gradBottom),
      smoothstep(0.0, 1.0, uv().y)
    ),
  });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  // === LIGHTING ===
  // Key light (warm, directional)
  const keyLight = new PointLight(0xffffff, 1.2, 20);
  keyLight.position.set(2.0, 1.5, 2.5);
  group.add(keyLight);

  // Rim light (accent hue, opposite side)
  const rimLight = new PointLight(0xff2a38, 0.7, 20);
  rimLight.position.set(-2.5, -1.0, 1.8);
  group.add(rimLight);

  // === HEADER CAPTION ===
  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
  });
  headerText.position.set(gridOffsetX, gridOffsetY + gridHeight / 2 + 0.5, 0.2);
  group.add(headerText);

  // === CELL FACTORY ===
  function createCell(x, y, width, height, valueFontSize, valueText, labelText) {
    const cellGroup = new Group();
    cellGroup.position.set(x, y, 0);

    // Main surface: extruded slab with diagonal gradient
    const surfaceGeom = new BoxGeometry(width, height, cellDepth);

    // Diagonal gradient (135 deg) with engineered hard stops
    const surfaceMat = new MeshStandardNodeMaterial({
      colorNode: mix(
        color(colors.gradTop),
        color(colors.gradBottom),
        smoothstep(0.25, 0.6, mix(uv().x, uv().y, 0.707)) // diagonal blend
      ),
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
      emissiveIntensity: 0,
    });

    const surfaceMesh = new Mesh(surfaceGeom, surfaceMat);
    surfaceMesh.castShadow = true;
    surfaceMesh.receiveShadow = true;
    surfaceMesh.userData.isCell = true;
    cellGroup.add(surfaceMesh);

    // Chamfer edge (beveled appearance via small extrusion)
    const chamferGeom = new BoxGeometry(width + 0.08, height + 0.08, cellDepth + 0.02);
    const chamferMat = new MeshStandardNodeMaterial({
      color: colors.surface,
      roughness: 0.6,
      metalness: 0.4,
      clearcoat: 0.15,
      emissiveIntensity: 0,
    });
    const chamferMesh = new Mesh(chamferGeom, chamferMat);
    chamferMesh.position.z = -0.01;
    cellGroup.add(chamferMesh);

    // Accent tick bar (top-left inside padding)
    const tickGeom = new PlaneGeometry(tickWidth, tickHeight);
    const tickMat = new MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: tickEmissive,
      metalness: 0.2,
      roughness: 0.5,
    });
    const tickMesh = new Mesh(tickGeom, tickMat);
    tickMesh.position.set(
      -width / 2 + innerPadding + tickWidth / 2,
      height / 2 - innerPadding - tickHeight / 2,
      cellDepth / 2 + 0.025
    );
    cellGroup.add(tickMesh);

    // Value text
    const valueTextObj = ctx.fontAtlas.createText(valueText, {
      fontSize: valueFontSize,
      color: colors.paper,
      align: 'left',
    });
    valueTextObj.position.set(
      -width / 2 + innerPadding,
      height / 2 - innerPadding - 0.15,
      cellDepth / 2 + 0.035
    );
    valueTextObj.userData.role = 'value';
    cellGroup.add(valueTextObj);

    // Label text
    const labelTextObj = ctx.fontAtlas.createText(labelText, {
      fontSize: 18,
      color: colors.paper,
      align: 'left',
    });
    labelTextObj.position.set(
      -width / 2 + innerPadding,
      height / 2 - innerPadding - 0.5,
      cellDepth / 2 + 0.035
    );
    labelTextObj.userData.role = 'label';
    cellGroup.add(labelTextObj);

    return cellGroup;
  }

  // === CREATE CELLS ===
  const dominantCell = createCell(
    dominantX,
    dominantY,
    dominantWidth,
    dominantHeight,
    62, // 0.62 unit em height
    '0.002 mm',
    'Case tolerance, CNC pass'
  );
  group.add(dominantCell);

  const secondary1Cell = createCell(
    secondary1X,
    secondary1Y,
    secondaryWidth,
    secondaryHeight,
    34, // 0.34 unit em height
    '38 h',
    'Power reserve, NA-01'
  );
  group.add(secondary1Cell);

  const secondary2Cell = createCell(
    secondary2X,
    secondary2Y,
    secondaryWidth,
    secondaryHeight,
    34, // 0.34 unit em height
    '214',
    'Components per calibre'
  );
  group.add(secondary2Cell);

  const cells = [dominantCell, secondary1Cell, secondary2Cell];

  // === ENTRANCE ANIMATION (stagger fade-up) ===
  const tlEntrance = gsap.timeline();

  cells.forEach((cellGroup, cellIdx) => {
    // Collect animatable children
    cellGroup.children.forEach((child) => {
      // Initial state
      child.userData.originalScale = child.scale.clone();

      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }

      // Fade in + slide up
      tlEntrance.from(
        child.position,
        {
          y: child.position.y + 0.2,
          duration: 0.5,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        cellIdx * 0.08
      );

      if (child.material) {
        tlEntrance.from(
          child.material,
          {
            opacity: 0,
            duration: 0.5,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
          },
          cellIdx * 0.08
        );
      }
    });
  });

  // === HOVER INTERACTION ===
  const pressTimelines = {};

  function attachCellInteraction(cellGroup) {
    cellGroup.userData.handlers = cellGroup.userData.handlers || {};
    const originalScale = new Vector3(1, 1, 1);

    cellGroup.userData.handlers.hover = function (isHovering) {
      const tlKey = cellGroup.uuid;

      if (pressTimelines[tlKey]) {
        pressTimelines[tlKey].kill();
      }

      if (isHovering) {
        // Press down: 1.0 -> 0.97 in 120ms
        const tlPress = gsap.timeline();
        pressTimelines[tlKey] = tlPress;

        tlPress.to(
          cellGroup.scale,
          {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          }
        );

        // Overshoot to 1.04 over next 300ms
        tlPress.to(
          cellGroup.scale,
          {
            x: 1.04,
            y: 1.04,
            z: 1.04,
            duration: 0.3,
            ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
          },
          0.12
        );

        // Weighted settle: 1.04 -> 1.0 over 900ms
        tlPress.to(
          cellGroup.scale,
          {
            x: 1.0,
            y: 1.0,
            z: 1.0,
            duration: 0.9,
            ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
          },
          0.42
        );
      }
    };
  }

  cells.forEach(attachCellInteraction);

  // === CLEANUP ===
  group.userData.cleanup = function () {
    if (tlEntrance) tlEntrance.kill();
    Object.values(pressTimelines).forEach((tl) => {
      if (tl) tl.kill();
    });
    cells.forEach((cell) => {
      gsap.killTweensOf(cell.scale);
      cell.traverse((node) => {
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach((m) => m.dispose());
          } else {
            node.material.dispose();
          }
        }
        if (node.geometry) {
          node.geometry.dispose();
        }
      });
    });
    backdropMesh.geometry.dispose();
    backdropMesh.material.dispose();
    keyLight.dispose?.();
    rimLight.dispose?.();
  };

  return group;
}
